namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = CreateSeedData();
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<RecipeCategory> GetCategories() =>
    [
        new() { Name = "Breakfast", Icon = "🥞", Description = "Start your day with delicious morning meals" },
        new() { Name = "Lunch", Icon = "🥗", Description = "Midday meals to keep you going" },
        new() { Name = "Dinner", Icon = "🍝", Description = "Hearty evening dishes for the whole family" },
        new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats to satisfy your cravings" },
        new() { Name = "Snacks", Icon = "🍿", Description = "Quick bites for any time of day" },
        new() { Name = "Drinks", Icon = "🍹", Description = "Refreshing beverages and cocktails" },
    ];

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    private static List<Recipe> CreateSeedData() =>
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Description = "Fluffy golden pancakes perfect for a weekend breakfast.",
            Ingredients = ["2 cups flour", "2 eggs", "1½ cups milk", "2 tbsp sugar", "2 tsp baking powder", "¼ tsp salt", "3 tbsp melted butter"],
            Steps = ["Mix dry ingredients in a bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just blended.", "Cook on a greased griddle over medium heat until bubbles form, then flip.", "Serve with maple syrup and fresh berries."],
            TotalRatings = 12, RatingSum = 52
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Description = "Simple, healthy, and absolutely delicious.",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper", "Red pepper flakes", "2 eggs (optional)"],
            Steps = ["Toast the bread until golden and crispy.", "Mash avocado with lemon juice, salt, and pepper.", "Spread avocado mixture on toast.", "Top with red pepper flakes and a fried egg if desired."],
            TotalRatings = 8, RatingSum = 35
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Description = "A classic Caesar salad with homemade croutons.",
            Ingredients = ["1 head romaine lettuce", "½ cup parmesan cheese", "1 cup croutons", "Caesar dressing", "Grilled chicken (optional)"],
            Steps = ["Wash and chop the romaine lettuce.", "Toss lettuce with Caesar dressing.", "Top with parmesan cheese and croutons.", "Add grilled chicken for extra protein."],
            TotalRatings = 6, RatingSum = 25
        },
        new()
        {
            Id = 4, Title = "Spaghetti Bolognese", Category = "Dinner",
            Description = "A rich and hearty Italian meat sauce over pasta.",
            Ingredients = ["1 lb spaghetti", "1 lb ground beef", "1 onion, diced", "3 cloves garlic", "1 can crushed tomatoes", "2 tbsp tomato paste", "1 tsp Italian seasoning", "Salt and pepper"],
            Steps = ["Cook spaghetti according to package directions.", "Brown ground beef with onion and garlic.", "Add crushed tomatoes, tomato paste, and seasoning.", "Simmer sauce for 20 minutes.", "Serve sauce over spaghetti with parmesan."],
            TotalRatings = 15, RatingSum = 68
        },
        new()
        {
            Id = 5, Title = "Chicken Stir-Fry", Category = "Dinner",
            Description = "Quick and colorful weeknight stir-fry.",
            Ingredients = ["2 chicken breasts, sliced", "2 cups mixed vegetables", "3 tbsp soy sauce", "1 tbsp sesame oil", "1 tbsp cornstarch", "Rice for serving"],
            Steps = ["Slice chicken and toss with cornstarch.", "Heat sesame oil in a wok over high heat.", "Cook chicken until golden, then remove.", "Stir-fry vegetables for 3 minutes.", "Return chicken, add soy sauce, and toss to combine.", "Serve over steamed rice."],
            TotalRatings = 10, RatingSum = 42
        },
        new()
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Decadent individual cakes with a molten chocolate center.",
            Ingredients = ["4 oz dark chocolate", "½ cup butter", "1 cup powdered sugar", "2 eggs", "2 egg yolks", "6 tbsp flour"],
            Steps = ["Preheat oven to 425°F. Grease ramekins.", "Melt chocolate and butter together.", "Stir in powdered sugar, eggs, egg yolks, and flour.", "Pour into ramekins and bake 12–14 minutes.", "Let stand 1 minute, then invert onto plates."],
            TotalRatings = 20, RatingSum = 95
        },
        new()
        {
            Id = 7, Title = "Trail Mix Energy Bites", Category = "Snacks",
            Description = "No-bake energy bites packed with wholesome ingredients.",
            Ingredients = ["1 cup oats", "½ cup peanut butter", "⅓ cup honey", "½ cup chocolate chips", "½ cup dried cranberries", "1 tsp vanilla"],
            Steps = ["Mix all ingredients in a bowl.", "Refrigerate for 30 minutes.", "Roll into 1-inch balls.", "Store in the refrigerator for up to a week."],
            TotalRatings = 7, RatingSum = 30
        },
        new()
        {
            Id = 8, Title = "Mango Smoothie", Category = "Drinks",
            Description = "A tropical and refreshing mango smoothie.",
            Ingredients = ["1 cup frozen mango", "1 banana", "1 cup yogurt", "½ cup orange juice", "1 tbsp honey"],
            Steps = ["Add all ingredients to a blender.", "Blend until smooth.", "Pour into glasses and serve immediately."],
            TotalRatings = 5, RatingSum = 22
        },
    ];
}

@rendermode InteractiveServer
@using RecipeCommunity.Services

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (_userRating ?? 0) ? "selected" : "") @(star <= HoverStar ? "hovered" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => HoverStar = star"
                  @onmouseout="() => HoverStar = 0"
                  role="button"
                  title="Rate @star star@(star > 1 ? "s" : "")">
                @(star <= (HoverStar > 0 ? HoverStar : (_userRating ?? 0)) ? "★" : "☆")
            </span>
        }
    </div>
    @if (_submitted)
    {
        <span class="rating-feedback text-success">Thanks for rating!</span>
    }
    else
    {
        <span class="rating-hint text-muted">Click to rate</span>
    }
    <div class="average-display text-muted mt-1">
        @if (AverageRating > 0)
        {
            <small>Average: @AverageRating.ToString("0.0") / 5 (@TotalRatings ratings)</small>
        }
        else
        {
            <small>No ratings yet</small>
        }
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private int? _userRating;
    private bool _submitted;
    private int HoverStar { get; set; }

    private void Rate(int stars)
    {
        _userRating = stars;
        _submitted = true;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            AverageRating = recipe.AverageRating;
            TotalRatings = recipe.TotalRatings;
        }
    }
}

