{"file_text": "@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services

<PageTitle>Submit a Recipe</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h2>📝 Submit a Recipe</h2>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@_model.Title</strong>" has been added to the @_model.Category category.</p>
        <a href="category/@_model.Category" class="btn btn-outline-success btn-sm">View Category</a>
        <button class="btn btn-outline-primary btn-sm ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category" class="form-select">
                <option value="">-- Select a category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat.Name">@cat.Icon @cat.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label for="description" class="form-label">Description</label>
            <InputTextArea id="description" @bind-Value="_model.Description" class="form-control" rows="2" placeholder="A short description of your recipe" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="_ingredientsText" class="form-control" rows="5" placeholder="Enter one ingredient per line" />
            <small class="form-text text-muted">One ingredient per line</small>
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" @bind-Value="_stepsText" class="form-control" rows="5" placeholder="Enter one step per line" />
            <small class="form-text text-muted">One step per line</small>
        </div>

        <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe _model = new();
    private string _ingredientsText = string.Empty;
    private string _stepsText = string.Empty;
    private bool _submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(_model.Title)
        && !string.IsNullOrWhiteSpace(_model.Category)
        && !string.IsNullOrWhiteSpace(_ingredientsText)
        && !string.IsNullOrWhiteSpace(_stepsText);

    private void HandleSubmit()
    {
        _model.Ingredients = _ingredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();
        _model.Steps = _stepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        RecipeService.AddRecipe(_model);
        _submitted = true;
    }

    private void Reset()
    {
        _model = new();
        _ingredientsText = string.Empty;
        _stepsText = string.Empty;
        _submitted = false;
    }
}
