toolArgs.new_str:
@page "/"
@using RecipeCommunity.Services

<PageTitle>Recipe Community</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">🍳 Recipe Community</h1>
    <p class="lead text-muted">Discover, share, and rate delicious recipes from our community.</p>
</div>

<div class="row g-4">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 col-sm-6">
            <a href="category/@category.Name" class="text-decoration-none">
                <div class="card h-100 shadow-sm category-card">
                    <div class="card-body text-center">
                        <div class="display-3 mb-3">@category.Icon</div>
                        <h4 class="card-title">@category.Name</h4>
                        <p class="card-text text-muted">@category.Description</p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="text-center mt-5">
    <p class="text-muted mb-2">Have a recipe to share?</p>
    <a href="submit" class="btn btn-primary btn-lg">Submit a Recipe</a>
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;
}

